mapper.sql:
WHERE i.deleted = 0

    AND (i.name LIKE CONCAT('%',#{keyword},'%')
         OR i.rfid_code LIKE CONCAT('%',#{keyword},'%')
         OR i.brand LIKE CONCAT('%',#{keyword},'%')
         OR i.model LIKE CONCAT('%',#{keyword},'%')
         OR i.spec LIKE CONCAT('%',#{keyword},'%'))


    AND i.space_id IN
    #{sid}


    AND i.category_id = #{categoryId}


    AND i.granularity = #{granularity}


    AND i.status = #{status}


    AND i.rfid_code IS NOT NULL AND i.rfid_code != ''
    AND (i.rfid_code IS NULL OR i.rfid_code = '')

mapper.select:
SELECT i.* FROM inv_item i

ORDER BY i.id DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE inv_item
SET name = #{name}, category_id = #{categoryId}, space_id = #{spaceId},
    granularity = #{granularity}, qty = #{qty}, status = #{status},
    icon_type = #{iconType}, icon_value = #{iconValue}, cover_url = #{coverUrl}, detail_images = #{detailImages}, brand = #{brand}, model = #{model},
    spec = #{spec}, expire_at = #{expireAt}, supplier = #{supplier}, purchase_no = #{purchaseNo},
    price = #{price}, purchase_date = #{purchaseDate}, warranty_until = #{warrantyUntil},
    fund_source = #{fundSource}, ext = #{ext}
    , rfid_code = #{rfidCode}
WHERE id = #{id}

mapper.select:
SELECT * FROM inv_item WHERE deleted = 0 AND status != 'RETIRED'
AND space_id IN #{sid}
AND 1 = 0
